// Canonical keccak256 script library (external-library / side-car pattern).
//
// KECCAK256_LIBRARY_BLOB is a one-shot REGISTRAR (stack in: [callableId]): run once, it OP_DEFINEs the keccak
// round (a reserved keccak-internal id, 2) and the keccak-main function at the CONSUMER-PROVIDED callableId,
// the latter padding + absorbing an arbitrary-length message (single-tx limit ~408 bytes; see keccak-poc/
// INTEGRATION.md and README.md). It lives in a side-car UTXO; a contract loads it by introspection, verifies
// it by hash (KECCAK256_LIBRARY_BLOB_HASH), pushes the compiler-assigned library id, OP_DEFINEs the registrar
// under a transient setup id, and OP_INVOKEs it ONCE. Call-sites then OP_INVOKE that id any number of times -
// the round is defined once and never redefined, so keccak256 is RE-ENTRANT (multiple keccak256 calls, or
// keccak256(keccak256(x)), in one input). The callable id is NOT baked into the blob, so it never assumes a
// fixed library id (the compiler deconflicts library ids and the loader supplies the right one).
//
// Generated from keccak-poc/genvar.mjs genKeccakRegistrar() - run keccak-poc/regen-utils-blob.mjs to
// regenerate. The compiler's loader offsets MUST match the SDK's side-car redeem byte-for-byte.

import { hexToBin } from '@bitauth/libauth';
import { Op, Script, scriptToBytecode } from './script.js';
import { hash256 } from './hash.js';

export const KECCAK256_LIBRARY_BLOB = '';
export const KECCAK256_LIBRARY_BLOB_HASH = '9743350a54a2fbd59fe22787d29d6eac48fce02e3ab2ad579619bf162c0a5e58';   // hash256(blob); baked into the integrity check
export const KECCAK256_LIBRARY_BLOB_LENGTH = 2331;
export const KECCAK256_LIBRARY_ID = 0x1009n;                 // next after the 0x1000-0x1008 subroutine registry

// Side-car redeem layout the loader strips past (must match the SDK builder):
//   <salt:32> OP_DROP | self-pres(6) | PUSHDATA2-prefix(3) | blob | OP_DROP OP_1
// branded: salt = contract token category; shared: salt = 32 zero bytes.
export const KECCAK256_SIDECAR_SALT_PREFIX_LENGTH = 34;      // OP_PUSHBYTES_32 + 32 + OP_DROP
export const KECCAK256_SIDECAR_SELFPRES_LENGTH = 6;          // self-pres recreates against last output
export const KECCAK256_SIDECAR_BLOB_PUSH_PREFIX_LENGTH = 3;  // OP_PUSHDATA2 + 2-byte length
export const KECCAK256_SIDECAR_OUTER_PUSH_PREFIX_LENGTH = 3; // unlocking = PUSHDATA2(redeem)

/**
 * Build the side-car redeem script: <salt:32> OP_DROP | self-pres | PUSHDATA2(blob) | OP_DROP OP_1.
 * Layout matches the compiler loader's strip offsets above (verify byte-for-byte). salt = the contract
 * token category (branded) or 32 zero bytes (shared). self-pres recreates the side-car at its own index.
 */
export function buildKeccakSidecarRedeem(salt: Uint8Array): Uint8Array {
  if (salt.length !== 32) throw new Error('keccak side-car salt must be 32 bytes');
  // self-pres: own locking bytecode == the LAST output's locking bytecode (recreate the library UTXO).
  // Decoupled from the input index so the SDK can append the side-car as the last input + last output.
  const script: Script = [
    salt, Op.OP_DROP,
    Op.OP_INPUTINDEX, Op.OP_UTXOBYTECODE, Op.OP_TXOUTPUTCOUNT, Op.OP_1SUB, Op.OP_OUTPUTBYTECODE, Op.OP_EQUALVERIFY,
    hexToBin(KECCAK256_LIBRARY_BLOB), Op.OP_DROP, Op.OP_1,
  ];
  return scriptToBytecode(script);
}

/** P2SH32 locking bytecode for the side-car: OP_HASH256 <hash256(redeem)> OP_EQUAL. */
export function keccakSidecarLockingBytecode(salt: Uint8Array): Uint8Array {
  return Uint8Array.from([0xaa, 0x20, ...hash256(buildKeccakSidecarRedeem(salt)), 0x87]);
}

/** Shared (unbranded) side-car salt: 32 zero bytes. */
export const KECCAK256_SHARED_SALT = new Uint8Array(32);
